// Hors ligne : tout le paquet est mis en cache à la première visite.
// Version generated by scripts/sync_site.py; keep each hosted project’s caches separate.
const CACHE_VERSION='029709e5f74a609f';
const CACHE_PREFIX='inga:'+self.registration.scope+':';
const CACHE=CACHE_PREFIX+CACHE_VERSION;
const FILES=["./", "fonts/architects-daughter-latin-400-normal.woff2", "fonts/architects-daughter-latin-ext-400-normal.woff2", "fonts/fonts.css", "fonts/ibm-plex-mono-latin-400-normal.woff2", "fonts/ibm-plex-mono-latin-500-normal.woff2", "fonts/ibm-plex-mono-latin-ext-400-normal.woff2", "fonts/ibm-plex-mono-latin-ext-500-normal.woff2", "fonts/ibm-plex-sans-condensed-latin-400-normal.woff2", "fonts/ibm-plex-sans-condensed-latin-500-normal.woff2", "fonts/ibm-plex-sans-condensed-latin-600-normal.woff2", "fonts/ibm-plex-sans-condensed-latin-700-normal.woff2", "fonts/ibm-plex-sans-condensed-latin-ext-400-normal.woff2", "fonts/ibm-plex-sans-condensed-latin-ext-500-normal.woff2", "fonts/ibm-plex-sans-condensed-latin-ext-600-normal.woff2", "fonts/ibm-plex-sans-condensed-latin-ext-700-normal.woff2", "fonts/ibm-plex-sans-latin-400-normal.woff2", "fonts/ibm-plex-sans-latin-500-normal.woff2", "fonts/ibm-plex-sans-latin-600-normal.woff2", "fonts/ibm-plex-sans-latin-ext-400-normal.woff2", "fonts/ibm-plex-sans-latin-ext-500-normal.woff2", "fonts/ibm-plex-sans-latin-ext-600-normal.woff2", "icons/icon-192.png", "icons/icon-512.png", "index.html", "lib/OrbitControls.js", "lib/three.min.js", "manifest.webmanifest", "musee.html", "voix/stop1.mp3", "voix/stop2.mp3", "voix/stop3.mp3", "voix/stop4.mp3", "voix/stop5.mp3", "voix/stop6.mp3", "voix/stop7.mp3", "voix/stop8.mp3"];
self.addEventListener('install',e=>{ e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())); });
self.addEventListener('activate',e=>{ e.waitUntil(caches.keys().then(ks=>Promise.all(ks.filter(k=>k.startsWith(CACHE_PREFIX)&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())); });
self.addEventListener('fetch',e=>{ if(e.request.method!=='GET') return; e.respondWith(caches.open(CACHE).then(c=>c.match(e.request,{ignoreSearch:true})).then(r=>r||fetch(e.request))); });
